import { readFileSync } from "node:fs";
import { join, relative } from "node:path";
import { describe, expect, it } from "vitest";
import { files } from "../harness/source";

const SRC = join(process.cwd(), "src");
const TONE_CSS = join(SRC, "components/_shared/feedback/feedback-tone.css");

/** Block comments out of CSS/TS, line comments out of TS. */
function strip(text: string): string {
    return text.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:])\/\/.*$/gm, "$1");
}

const SCAN_EXTS = [".css", ".ts", ".vue", ".mts"];

// FD-6 / R-3: a whole-library scan reads the harness's file set, never a directory walk; a
// unit's __tests__/ slot is test code, not the source it scans.
function walk(dir: string): string[] {
    return files({ under: relative(process.cwd(), dir) })
        .filter((f) => SCAN_EXTS.some((e) => f.endsWith(e)))
        .map((f) => join(process.cwd(), f));
}

